cat > /tmp/unused_imports.py <<'EOF'
import os, re, sys

root = sys.argv[1]
results = []
for dirpath, dirnames, filenames in os.walk(root):
    if 'target' in dirpath.split(os.sep):
        continue
    for fn in filenames:
        if not fn.endswith('.java'):
            continue
        p = os.path.join(dirpath, fn)
        try:
            with open(p, encoding='utf-8') as f:
                lines = f.readlines()
        except Exception:
            continue
        imports = []
        body_lines = []
        for i, l in enumerate(lines):
            m = re.match(r'\s*import\s+(static\s+)?([\w.]+)\s*;', l)
            if m:
                imports.append((i, m.group(1) is not None, m.group(2), l.rstrip('\n')))
            else:
                body_lines.append(l)
        body = ''.join(body_lines)
        unused = []
        for (i, isstatic, fq, raw) in imports:
            last = fq.split('.')[-1]
            if last == '*':
                continue
            if not re.search(r'\b' + re.escape(last) + r'\b', body):
                unused.append((i+1, raw.strip()))
        if unused:
            results.append((p, unused))

results.sort()
tot = 0
for p, u in results:
    print(p)
    for ln, raw in u:
        tot += 1
        print('   %5d  %s' % (ln, raw))
print('FILES', len(results), 'IMPORTS', tot)
EOF
